const req = $input.first().json.body || $input.first().json;

const amount = Number(req.amount || 5000);
const nav = Number(req.nav || 100);
const units = Number((amount / nav).toFixed(4));

return {
  json: {
    success: true,
    intent: 'WEALTH',
    subIntent: 'INVESTMENT_SIMULATION',
    mode: 'SIMULATION',
    disclaimer: 'This is a simulated transaction. No real money was invested.',
    data: {
      userId: req.userId,
      fundId: req.fundId,
      fundName: req.fundName || 'Simulated Fund',
      amount,
      nav,
      units,
      mode: 'SIMULATION',
      status: 'Completed',
      transactionDate: new Date().toISOString()
    },
    timestamp: new Date().toISOString()
  }
};
